/* RLT Skill Building 15.12.120 · 14 eigenständig verfasste fiktive Übungsfälle. Keine Original-Manualfragen oder Klientendaten. */
window.BDRLT120Cases=[{"id":"rm-01","track":"Relational Mindfulness","title":"Der Moment vor dem Gegenangriff","skill":"Frühe Aktivierung erkennen und die eigene Wahlfreiheit zurückgewinnen","context":"Mira und Luis berichten von einem Streit nach einer verspäteten Nachricht. Die Stimmung wird im Gespräch zunehmend enger.","scene":[{"speaker":"Mira","text":"Als du drei Stunden nicht geantwortet hast, habe ich gedacht, ich bin dir egal."},{"speaker":"Luis","text":"Du hast mich viermal angerufen. Das hat mich echt unter Druck gesetzt."},{"speaker":"Mira","text":"Ich wollte nur wissen, ob alles okay ist."},{"speaker":"Luis","text":"Wenn du mich so ansprichst, will ich sofort zurückschießen."},{"speaker":"Mira","text":"Und dann sagst du etwas Verletzendes."},{"speaker":"Luis","text":"Ja. Ich merke gerade schon, wie ich innerlich Argumente sammle."}],"anchor":"Relational Mindfulness: den aktivierten Schutzimpuls bemerken, regulieren und erst danach eine relationale Entscheidung treffen. Die Pause ist ein Schritt im Kontakt, nicht dessen Abbruch.","caution":"Ein Moment der Selbstregulation ersetzt weder die Klärung berechtigter Bedürfnisse noch die Verantwortung für verletzende Worte.","first":[{"text":"„Luis, Sie merken den Impuls zum Zurückschießen schon jetzt. Woran spüren Sie ihn körperlich – und könnten wir diesen Moment kurz verlangsamen?“","grade":3,"why":"Greift seine eigene Beobachtung auf und schafft Wahlfreiheit vor der nächsten Reaktion.","response":"Luis: „Mein Kiefer wird hart. Wenn ich kurz warte, muss ich vielleicht nicht sofort etwas sagen.“"},{"text":"„Welche Form von Nachricht würde Ihnen beiden künftig mehr Sicherheit geben?“","grade":2,"why":"Eine konkrete Vereinbarung kann hilfreich sein; im Moment ist Luis schon sichtbar aktiviert.","response":"Luis: „Vielleicht später. Gerade merke ich, wie ich mich rechtfertigen will.“"},{"text":"„Mira, was haben Sie genau gehört, bevor Luis gereizt wurde?“","grade":1,"why":"Perspektivklärung ist grundsätzlich möglich, lässt aber den gerade benannten Eskalationsimpuls unbeachtet.","response":"Mira: „Ich weiß nicht. Er schaut schon wieder weg.“"}],"follow_good":[{"text":"„Was ändert sich gerade, wenn Sie den Kiefer entspannen und Mira ansehen?“","grade":3,"why":"Macht die unmittelbare Verbindung zwischen Selbstregulation und Kontakt überprüfbar.","response":"Luis: „Ich kann hören, dass sie Angst hatte. Vorher habe ich nur Vorwürfe gehört.“"},{"text":"„Könnten Sie ihr jetzt in einem Satz erklären, warum Sie nicht antworten konnten?“","grade":2,"why":"Sachinformation kann helfen; sie riskiert aber, erneut in Rechtfertigung zu kippen.","response":"Mira: „Ich wünsche mir zuerst, dass er meine Sorge versteht.“"},{"text":"„Sollten wir festlegen, dass Luis künftig spätestens nach zwei Stunden reagiert?“","grade":1,"why":"Eine Regel ist verhandelbar, aber ohne beiderseitige Zustimmung und Bedürfnisverständnis zu früh.","response":"Luis: „Dann fühle ich mich schon wieder kontrolliert.“"}],"follow_repair":[{"text":"„Ich bin gerade zu schnell beim Organisieren gelandet. Luis, Ihr Impuls zum Gegenangriff ist hier schon spürbar. Können wir ihn erst gemeinsam beobachten?“","grade":3,"why":"Repariert die vorschnelle Problemlösung und kehrt zum aktivierten Moment zurück.","response":"Luis: „Ja, das ist eigentlich das Problem. Ich schalte sofort auf Verteidigung.“"},{"text":"„Mira, können Sie einen Moment pausieren, damit Luis sich sammelt?“","grade":2,"why":"Ein Pauseangebot ist plausibel, muss aber als gemeinsamer, transparenter Schritt gestaltet werden.","response":"Mira: „Ja, wenn er mir sagt, dass er wiederkommt.“"},{"text":"„Vielleicht ist es hilfreicher, erstmal ausführlich über die Telefonregel zu sprechen.“","grade":1,"why":"Eine Regel löst die akute Reaktivität noch nicht und könnte den Prozess übergehen.","response":"Luis: „Ich bin dafür gerade zu aufgewühlt.“"}],"model":"„Ich sehe bei Ihnen beiden Sorge. Luis, bevor Sie antworten: Wo merken Sie den Gegenangriff im Körper? Können Sie einen Augenblick innehalten und dann Mira sagen, was Sie von ihrer Sorge verstanden haben?“","rubric":["Aktivierung an beobachtbaren Signalen verankert","Pause als freiwillige Rückkehr in den Kontakt","Keine Schuldzuweisung für Gefühle","Konkrete nächste relationale Handlung"]},{"id":"rm-02","track":"Relational Mindfulness","title":"Die Rechtfertigung schießt hoch","skill":"Zwischen berechtigter Selbstvertretung und reaktivem Beweisen unterscheiden","context":"Nora bittet um mehr Beteiligung im Haushalt. Erik erlebt die Bitte als Kritik seiner Person.","scene":[{"speaker":"Nora","text":"Ich möchte, dass du die Morgenroutine öfter selbst übernimmst."},{"speaker":"Erik","text":"Ich habe gestern die Küche gemacht und vorgestern die Wäsche."},{"speaker":"Nora","text":"Das stimmt. Mir geht es um die Morgen."},{"speaker":"Erik","text":"Ich will zeigen, dass ich nicht faul bin."},{"speaker":"Nora","text":"Ich habe das Wort faul nicht gesagt."},{"speaker":"Erik","text":"Ich höre es trotzdem sofort."}],"anchor":"Relational Mindfulness: zwischen dem aktuellen Anliegen und der eigenen alten inneren Geschichte unterscheiden, ohne sich für ein Gefühl zu verurteilen.","caution":"Biografische Hypothesen dürfen nicht als Diagnose über Eriks Vergangenheit behauptet werden.","first":[{"text":"„Erik, Nora bittet um die Morgenroutine. Bei Ihnen taucht sofort die Botschaft ‚ich bin faul‘ auf. Wollen wir diese beiden Ebenen kurz auseinanderhalten?“","grade":3,"why":"Trennt gegenwärtige Beobachtung und persönliche Deutung; erhält seine Würde.","response":"Erik: „Ja. Sie hat das tatsächlich nicht gesagt. Es fühlt sich nur so an.“"},{"text":"„Erik, können Sie Nora aufzählen, was Sie bereits erledigen?“","grade":2,"why":"Sachliche Sichtbarkeit kann entlasten, führt hier aber leicht in einen Beweiswettstreit.","response":"Nora: „Ich weiß, dass er viel tut. Es geht um die Verteilung morgens.“"},{"text":"„Nora, könnten Sie die Bitte weniger vorwurfsvoll formulieren?“","grade":1,"why":"Prüfung der Formulierung ist möglich, übernimmt aber vorschnell Eriks Interpretation als Fakt.","response":"Nora: „Ich dachte, es war eine konkrete Bitte.“"}],"follow_good":[{"text":"„Können Sie die Bitte jetzt noch einmal hören, ohne mit der inneren Aussage ‚ich bin faul‘ antworten zu müssen?“","grade":3,"why":"Trainiert eine zweite, bewusst gewählte Reaktion auf denselben Reiz.","response":"Erik: „Ich höre: Sie braucht morgens mehr Entlastung.“"},{"text":"„Wollen wir direkt eine neue Aufgabenliste machen?“","grade":2,"why":"Nach Entkoppelung der Deutung sinnvoll, aber ein kurzes relationales Verstehen wäre vertiefend.","response":"Nora: „Gern, wenn er erst weiß, was ich meine.“"},{"text":"„Können Sie sich jetzt sofort bei Nora für Ihre Abwehr entschuldigen?“","grade":1,"why":"Entschuldigung kann angemessen sein; als Aufforderung vor echter Einsicht mechanisch.","response":"Erik: „Ich will verstehen, was genau ich da mache.“"}],"follow_repair":[{"text":"„Ich habe Sie gerade in eine Verteidigungssituation gebracht. Nora fragte nach den Morgen. Erik, wir können bei dieser Bitte bleiben und Ihre innere Geschichte danebenstellen.“","grade":3,"why":"Korrigiert den Prozess und stellt Datengrundlage her.","response":"Erik: „So kann ich eher zuhören.“"},{"text":"„Vielleicht sammeln wir zuerst beide Sichtweisen zum Haushalt.“","grade":2,"why":"Fairer Ansatz, aber noch keine klare Trennung von Bitte und innerer Zuschreibung.","response":"Nora: „Die Gesamtbilanz ist mir gerade weniger wichtig.“"},{"text":"„Erik, warum fällt Ihnen Anerkennung so schwer?“","grade":1,"why":"Könnte biografisch bedeutsam sein, ist hier aber eine ungestützte persönliche Zuschreibung.","response":"Erik: „Ich weiß nicht, ob das stimmt.“"}],"model":"„Erik, der Satz ‚ich bin faul‘ scheint sehr schnell in Ihnen aufzutauchen. Prüfen wir: Was hat Nora tatsächlich gesagt, und was hat Ihre innere Alarmanlage ergänzt?“","rubric":["Äußeres Ereignis und innere Deutung unterscheiden","Beide Personen respektvoll adressieren","Keine erfundene Herkunftsfamiliendiagnose","Erst verstehen, dann Haushaltslösung"]},{"id":"rm-03","track":"Relational Mindfulness","title":"Wenn die Beraterin selbst ungeduldig wird","skill":"Eigene Gegenreaktion wahrnehmen, ohne sie am Paar auszuagieren","context":"Ein Paar unterbricht sich zum vierten Mal. Du bemerkst als beratende Person, dass du am liebsten schnell eine Regel durchsetzen möchtest.","scene":[{"speaker":"Tina","text":"Sobald ich anfange, sprichst du dazwischen."},{"speaker":"Omar","text":"Weil sie ständig übertreibt."},{"speaker":"Tina","text":"Das ist wieder genau das Problem!"},{"speaker":"Omar","text":"Jetzt soll ich wohl wieder der Schuldige sein."},{"speaker":"Tina","text":"Ich kann meinen Satz nie zu Ende bringen."},{"speaker":"Omar","text":"Dann soll sie wenigstens bei den Fakten bleiben."}],"anchor":"Relational Mindfulness gilt auch für die beratende Person: eigene Aktivierung bemerken, nicht aus Ungeduld intervenieren und mit ruhiger Leitung den Prozess halten.","caution":"Strukturierende Unterbrechungen können fachlich notwendig sein; die eigene Regulation macht sie gezielter, ersetzt aber keine klare Grenze gegen Abwertung.","first":[{"text":"Du registrierst deine Ungeduld, senkst das Tempo und sagst: „Ich stoppe kurz, weil wir gerade mehrfach übereinander sprechen. Tina beendet ihren Satz, Omar hört zunächst nur zu.“","grade":3,"why":"Selbstwahrnehmung wird in eine klare, nicht beschämende Prozessintervention übersetzt.","response":"Tina: „Danke, ich möchte den Gedanken fertig sagen.“"},{"text":"Du gibst sofort beiden jeweils zwei Minuten Redezeit.","grade":2,"why":"Strukturierung ist plausibel, aber ohne Benennung des aktuellen Unterbrechungsmusters bleibt der Lernmoment unsichtbar.","response":"Omar: „Okay, aber ich will danach richtigstellen, was nicht stimmt.“"},{"text":"Du fragst Omar, weshalb Fakten für ihn gerade so wichtig sind.","grade":1,"why":"Neugier ist berechtigt, kann aber die aktuelle Unterbrechung erneut belohnen.","response":"Tina: „Dann war mein Satz wieder nicht dran.“"}],"follow_good":[{"text":"„Omar, was geschah innerlich, als Sie Tina ausreden ließen? Und Tina, was war daran anders?“","grade":3,"why":"Vertieft die erlebte Wirkung einer veränderten Prozessstruktur.","response":"Omar: „Ich habe erst zuhören müssen. Sie klang weniger vorwurfsvoll als gedacht.“"},{"text":"„Wollen Sie diese Redezeitregel ab jetzt immer einhalten?“","grade":2,"why":"Eine alltagstaugliche Struktur ist möglich, aber die eben entstandene Erfahrung braucht kurze Auswertung.","response":"Tina: „Es war gerade gut. Ich würde gern wissen, ob er mich gehört hat.“"},{"text":"„Dann können wir jetzt zum eigentlichen Sachthema zurückkehren.“","grade":1,"why":"Überspringt den beziehungsrelevanten Unterschied, der gerade erkennbar geworden ist.","response":"Omar: „Ich glaube, wir hätten noch etwas zu klären.“"}],"follow_repair":[{"text":"„Ich habe den Prozess eben nicht genug geschützt. Ich stoppe das gegenseitige Unterbrechen jetzt bewusst und mache die Reihenfolge für beide transparent.“","grade":3,"why":"Die Leitung übernimmt Verantwortung, ohne das Paar zu pathologisieren.","response":"Tina: „Gut. Dann versuche ich es noch einmal.“"},{"text":"„Ich merke viel Spannung. Wäre eine kurze Pause für beide hilfreich?“","grade":2,"why":"Kann angemessen sein, ist hier aber weniger zielgenau als das Unterbrechungsmuster zu stoppen.","response":"Omar: „Ich kann weitermachen, wenn wir uns ausreden lassen.“"},{"text":"„Sie müssen sich beide jetzt mehr anstrengen, einander zuzuhören.“","grade":1,"why":"Der Wunsch ist verständlich, aber zu allgemein und moralisiert.","response":"Tina: „Ich weiß bloß nicht, wie.“"}],"model":"„Ich merke, dass ich selbst schneller werden wollte. Ich bremse uns. Ich werde die Redezeiten schützen und im Anschluss mit Ihnen beiden betrachten, wie sich das gegenseitige Zuhören verändert.“","rubric":["Eigene emotionale Aktivierung erkannt","Konkrete Prozessgrenze statt Tadel","Keinen Partner bevorzugt","Neue Erfahrung im Hier und Jetzt ausgewertet"]},{"id":"gr-01","track":"Grenzen & Time-outs","title":"Eine Pause mit Rückkehr","skill":"Verantwortlichen Time-out von strafendem Schweigen unterscheiden","context":"Nach einem eskalierten Streit möchte Enno den Raum verlassen. Alina erlebt Rückzug oft als tagelanges Schweigen.","scene":[{"speaker":"Alina","text":"Wenn du gehst, weiß ich nie, wann wir wieder reden."},{"speaker":"Enno","text":"Weil ich sonst Sachen sage, die ich bereue."},{"speaker":"Alina","text":"Letzte Woche hast du zwei Tage geschwiegen."},{"speaker":"Enno","text":"Ich war wütend. Aber ich will nicht wieder laut werden."},{"speaker":"Alina","text":"Ich brauche, dass du wiederkommst."},{"speaker":"Enno","text":"Okay. Ich weiß nur nicht, wie ich das ankündigen soll."}],"anchor":"Verantwortlicher Time-out: Überforderung benennen, zeitlich begrenzte Selbstregulation vereinbaren und verbindliche Rückkehr anbieten; kein strafendes Schweigen.","caution":"Eine verbindliche Rückkehrregel darf nicht verwendet werden, um gefährdete Personen zu zwingen, einen unsicheren Kontakt wiederaufzunehmen.","first":[{"text":"„Enno, wie könnten Sie die Pause so ankündigen, dass Alina eine klare Rückkehrzeit kennt und Sie trotzdem zur Ruhe kommen?“","grade":3,"why":"Schützt Regulation und Vorhersehbarkeit gleichzeitig.","response":"Enno: „Ich brauche 30 Minuten und komme um acht zurück. Falls es länger dauert, sage ich Bescheid.“"},{"text":"„Könnten Sie beide vereinbaren, dass jede Person den Raum jederzeit ohne Erklärung verlassen darf?“","grade":2,"why":"Autonomie ist wichtig, aber die erlebte Strafwirkung des langen Schweigens bleibt ungeklärt.","response":"Alina: „Genau das macht mich so unsicher.“"},{"text":"„Alina, können Sie Enno versprechen, in der Pause nicht hinterherzugehen?“","grade":1,"why":"Nachgehen kann eskalieren, aber die Bitte legt Verantwortung einseitig bei Alina ab.","response":"Alina: „Ich brauche trotzdem ein Zeichen, dass er wiederkommt.“"}],"follow_good":[{"text":"„Was brauchen Sie beide, damit diese Rückkehr auch nach einem schwierigen Abend glaubwürdig bleibt?“","grade":3,"why":"Prüft konkrete Umsetzung statt bloßer Absicht.","response":"Alina: „Eine Uhrzeit.“ Enno: „Und die Erlaubnis, ruhig statt sofort gelöst zurückzukommen.“"},{"text":"„Möchten Sie die 30 Minuten als feste Regel übernehmen?“","grade":2,"why":"Konkrete Zeit ist hilfreich, sollte jedoch an Aktivierung und Alltag angepasst werden.","response":"Enno: „An manchen Tagen brauche ich etwas mehr.“"},{"text":"„Dann besprechen wir nur noch die Gründe für den Streit.“","grade":1,"why":"Überspringt die gerade entwickelte Selbstregulationsvereinbarung.","response":"Alina: „Ich möchte wissen, ob die Pause wirklich anders wird.“"}],"follow_repair":[{"text":"„Ich habe die Sicherheit der Rückkehr noch nicht ausreichend mitgedacht. Eine Pause braucht hier eine Ankündigung und einen verlässlichen nächsten Kontakt.“","grade":3,"why":"Repariert das Versäumnis und unterscheidet Pause von Kontaktentzug.","response":"Alina: „Damit könnte ich viel besser umgehen.“"},{"text":"„Wollen wir in einem zweiten Schritt anschauen, warum die Pause bisher so lang wurde?“","grade":2,"why":"Eine gute Anschlussfrage; eine neue konkrete Vereinbarung fehlt noch.","response":"Enno: „Ja, ich will das verstehen.“"},{"text":"„Vielleicht können Sie beide einfach mehr Geduld miteinander üben.“","grade":1,"why":"Plausibles Ziel, aber ohne klare Rückkehrpraxis zu unspezifisch.","response":"Alina: „Das sagt nichts darüber, wann wir wieder sprechen.“"}],"model":"„Ich möchte eine Pause unterstützen, die niemanden bestraft. Was ist eine realistische Dauer? Wie kündigt Enno sie an, und wie kommen Sie danach verlässlich wieder ins Gespräch?“","rubric":["Time-out nicht mit Schweigen gleichgesetzt","Rückkehr und Kontaktvereinbarung konkret","Beide Bedürfnisse berücksichtigt","Sicherheitsausnahmen bedacht"]},{"id":"gr-02","track":"Grenzen & Time-outs","title":"Eine Grenze ohne Kontrolle","skill":"Eigene Handlungsmöglichkeit statt Forderung an die andere Person formulieren","context":"Sofie fühlt sich durch spöttische Bemerkungen verletzt. Loris sagt, er wolle nur Humor in den Alltag bringen.","scene":[{"speaker":"Sofie","text":"Vor deinen Freunden machst du Witze über meine Arbeit."},{"speaker":"Loris","text":"Ich necke dich. Die anderen lachen auch."},{"speaker":"Sofie","text":"Ich lache nicht. Ich fühle mich bloßgestellt."},{"speaker":"Loris","text":"Dann darf man ja gar nichts mehr sagen."},{"speaker":"Sofie","text":"Ich will mit dir ausgehen können, ohne Angst vor dem nächsten Spruch."},{"speaker":"Loris","text":"Ich weiß nicht, wie wir da eine Grenze finden."}],"anchor":"Grenzen: benennen, was verletzend ist, welche eigene Handlung zum Schutz möglich ist und welche respektvolle Bitte daraus folgt; keine Kontrolle durch Drohung.","caution":"Bei wiederholter Demütigung und Einschüchterung reicht eine Kommunikationsübung allein möglicherweise nicht aus.","first":[{"text":"„Sofie, woran würden Sie merken, dass Ihre Grenze respektiert wird, und was werden Sie selbst tun, falls ein verletzender Spruch erneut fällt?“","grade":3,"why":"Hilft zu einer konkreten Grenze mit eigener Handlung statt Machtausübung.","response":"Sofie: „Ich werde es ansprechen und das Gespräch notfalls verlassen. Aber ich möchte vorher eine klare Absprache.“"},{"text":"„Loris, könnten Sie Sofie versprechen, künftig gar keine Witze mehr zu machen?“","grade":2,"why":"Schafft scheinbar Sicherheit, ist aber als Totalregel weniger differenziert als eine spezifische Grenze.","response":"Loris: „Ich weiß gar nicht, welcher Humor dann noch erlaubt ist.“"},{"text":"„Vielleicht überlegen Sie gemeinsam, wann ein Witz objektiv harmlos ist.“","grade":1,"why":"Nachvollziehbare Unterscheidung, rückt aber von Sofies konkret benannter Verletzung ab.","response":"Sofie: „Ich möchte nicht vor Gericht über meinen Humor-Geschmack stehen.“"}],"follow_good":[{"text":"„Loris, was haben Sie an Sofies Grenze verstanden – und worauf können Sie sich freiwillig einlassen?“","grade":3,"why":"Prüft wechselseitiges Verständnis und freiwillige Kooperation.","response":"Loris: „Ich kann Witze über ihre Arbeit lassen und nachfragen, wenn ich unsicher bin.“"},{"text":"„Sollten Sie die Vereinbarung möglichst genau schriftlich aufschreiben?“","grade":2,"why":"Kann Transparenz geben, ersetzt aber nicht das Verstehen der Wirkung.","response":"Sofie: „Mir wäre wichtiger, dass er ernst nimmt, warum es weh tut.“"},{"text":"„Dann können die gemeinsamen Treffen doch genauso weitergehen.“","grade":1,"why":"Zu schneller Abschluss ohne Erprobung und Einverständnis.","response":"Sofie: „Ich brauche erst Vertrauen in die Änderung.“"}],"follow_repair":[{"text":"„Ich habe die Frage zu sehr zu einem Verbot gemacht. Sofies Grenze beschreibt ihre Sicherheit; Loris soll verstehen können, welche Bemerkung sie verletzt und wie er sich dazu verhält.“","grade":3,"why":"Kehrt von pauschalem Kontrollelement zur konkreten Selbstgrenze zurück.","response":"Loris: „Bei der Arbeit ist es also etwas anderes als über eine lustige Filmszene.“"},{"text":"„Wollen wir zwei konkrete Beispiele sammeln, die Sofie als verletzend erlebt?“","grade":2,"why":"Hilft, das Verhalten zu präzisieren; eigene Handlung und Bitte fehlen noch.","response":"Sofie: „Ja, aber ich will auch wissen, was ich dann tun kann.“"},{"text":"„Loris, Humor bedeutet eben immer ein gewisses Risiko für Missverständnisse.“","grade":1,"why":"Mag abstrakt stimmen, relativiert hier Sofies deutlich kommunizierte Grenze.","response":"Sofie: „Er weiß seit Monaten, dass es mich verletzt.“"}],"model":"„Sofie, formulieren wir Ihre Grenze als eigene Position: ‚Wenn meine Arbeit vor anderen lächerlich gemacht wird, spreche ich es an und ziehe mich gegebenenfalls aus der Situation zurück. Ich wünsche mir, dass du darauf verzichtest.‘“","rubric":["Grenze mit beobachtbarem Verhalten verbunden","Eigene Konsequenz statt Drohkulisse","Wirkung auf Sofie ernst genommen","Kooperation nicht erzwungen"]},{"id":"gr-03","track":"Grenzen & Time-outs","title":"Wenn Zustimmung nicht frei wirkt","skill":"Sicherheit und Freiwilligkeit vor gemeinsamer Veränderungsarbeit prüfen","context":"Kim bejaht jede Frage schnell, schaut dabei aber immer wieder zu Robin. Robin spricht häufig für beide. Du kennst die Hintergründe noch nicht.","scene":[{"speaker":"Robin","text":"Wir sind bereit, die Regeln umzusetzen."},{"speaker":"Kim","text":"Ja, passt schon."},{"speaker":"Robin","text":"Kim weiß, dass wir dafür endlich konsequent sein müssen."},{"speaker":"Kim","text":"Ich würde gern erstmal nachdenken."},{"speaker":"Robin","text":"Wir haben das doch längst besprochen."},{"speaker":"Kim","text":"Ich will hier nichts Falsches sagen."}],"anchor":"Bei möglichen Einschränkungen von Freiwilligkeit zuerst einen sicheren Rahmen und eigenständige Stimmen prüfen; nicht vorschnell Symmetrie oder Konsens behaupten.","caution":"Bei Hinweisen auf Kontrolle oder Gewalt keine gemeinsame Konfrontation der möglicherweise betroffenen Person; individuelle, sichere Abklärung nach fachlicher Zuständigkeit.","first":[{"text":"„Ich möchte die Entscheidung noch nicht als gemeinsame Vereinbarung festhalten. Ich werde mit jeder Person getrennt und in sicherem Rahmen klären, ob die Zustimmung frei ist.“","grade":3,"why":"Priorisiert Freiwilligkeit und schützt vor möglicher Verschärfung unter Beobachtung.","response":"Fallnotiz: Kim erhält die Möglichkeit eines vertraulichen Einzelkontakts, ohne vor Robin Stellung beziehen zu müssen."},{"text":"„Kim, möchten Sie zunächst mehr Bedenkzeit, bevor wir etwas festlegen?“","grade":2,"why":"Respektiert das Zögern; eine offene Ablehnung vor Robin könnte jedoch riskant sein.","response":"Fallnotiz: Kim nickt, schaut jedoch erneut zu Robin."},{"text":"„Robin, könnten Sie Kim heute bewusst mehr Raum zum Antworten lassen?“","grade":1,"why":"Kann bei normaler Dominanz hilfreich sein, genügt bei möglicher Kontrolle aber nicht als Schutz.","response":"Fallnotiz: Robin erklärt ausführlich, dass bereits alles geklärt sei."}],"follow_good":[{"text":"„Wie kann ich Kim einen vertraulichen, selbstbestimmten Kontaktweg ermöglichen, ohne Robin gegenüber sensible Vermutungen offenzulegen?“","grade":3,"why":"Setzt Sicherheitsabklärung und Datenschutz praktisch um.","response":"Fallnotiz: Ein neutral organisierter Einzelkontakt wird vorbereitet; gemeinsame Regeln bleiben ausgesetzt."},{"text":"„Soll ich Robin die Vereinbarung in allgemeiner Form nochmals erläutern?“","grade":2,"why":"Transparenz kann sinnvoll sein, sollte aber keine Rückschlüsse auf vertrauliche Äußerungen erlauben.","response":"Fallnotiz: Die fachliche Information wird neutral gegeben, keine Zustimmung erzwungen."},{"text":"„Soll ich die neue Regel sofort für beide verbindlich dokumentieren?“","grade":1,"why":"Ein dokumentierter Konsens wäre verfrüht, da Kims Freiwilligkeit nicht geklärt ist.","response":"Fallnotiz: Der gemeinsame Plan wird nicht abgeschlossen."}],"follow_repair":[{"text":"„Ich korrigiere den Ablauf: Ohne sichere Prüfung von Kims Freiwilligkeit formuliere ich keine gemeinsame Veränderungsvereinbarung.“","grade":3,"why":"Sicherheitsorientierte Korrektur trotz Druck zu einem schnellen Paarplan.","response":"Fallnotiz: Die gemeinsame Aufgabenstellung wird pausiert; individueller Schutzrahmen wird angeboten."},{"text":"„Ich könnte das Gespräch beenden und später erneut anbieten.“","grade":2,"why":"Pausieren kann schützend sein, doch ein niedrigschwelliger sicherer Anschluss sollte geklärt werden.","response":"Fallnotiz: Es braucht einen verantwortbaren nächsten Kontakt."},{"text":"„Ich warte zunächst, ob Kim beim nächsten Termin widerspricht.“","grade":1,"why":"Fehlender Widerspruch ist kein Beleg für freie Zustimmung.","response":"Fallnotiz: Der notwendige Sicherheitscheck bleibt offen."}],"model":"„Bevor wir gemeinsame Absprachen treffen, ist mir wichtig, dass jede Person wirklich selbst entscheiden kann. Ich kläre das bei Bedarf einzeln und in einem geschützten Rahmen.“","rubric":["Freiwilligkeit ohne Druck geprüft","Kein erzwungenes öffentliches Bekenntnis","Vertrauliche Wege geschützt","Keine vorschnelle gemeinsame Intervention"]},{"id":"fw-01","track":"Feedback Wheel","title":"Die Geschichte hinter dem Handy","skill":"Feedback Wheel: Beobachtung und Interpretation auseinanderhalten","context":"Jule fühlte sich bei einem Abendessen übergangen, als Sam mehrfach aufs Handy schaute.","scene":[{"speaker":"Jule","text":"Beim Essen warst du dauernd am Handy."},{"speaker":"Sam","text":"Ich habe zweimal eine Nachricht gelesen."},{"speaker":"Jule","text":"Ich dachte, du interessierst dich nicht mehr für mich."},{"speaker":"Sam","text":"Das stimmt so nicht. Ich musste eine Nachricht vom Kind beantworten."},{"speaker":"Jule","text":"Ich war trotzdem traurig."},{"speaker":"Sam","text":"Das verstehe ich eher als den Satz, ich würde mich nicht für dich interessieren."}],"anchor":"Feedback Wheel in vier Schritten: (1) beobachtbares Ereignis, (2) eigene Geschichte/Deutung, (3) Gefühl, (4) konkrete Bitte – in dieser Reihenfolge und ohne Anspruch, dass die Deutung wahr ist.","caution":"Feedback ist keine Wahrheitsfindung über die Absicht des anderen. Der Empfänger darf seine Perspektive behalten.","first":[{"text":"„Jule, können Sie erst sagen, was Sie gesehen haben, und dann markieren: ‚Ich habe mir erzählt, dass …‘?“","grade":3,"why":"Trennt Beobachtung und Interpretation, ohne die emotionale Reaktion abzuwerten.","response":"Jule: „Ich sah die Nachrichten. Ich erzählte mir, dass unser Abend nicht wichtig ist.“"},{"text":"„Sam, können Sie erklären, weshalb Sie die Nachrichten geöffnet haben?“","grade":2,"why":"Sams Kontext ist wichtig, kann aber Jules Feedback vorzeitig in eine Rechtfertigungsschleife führen.","response":"Jule: „Ich möchte zuerst meine Erfahrung ausdrücken.“"},{"text":"„Vielleicht können Sie sich beide darauf einigen, dass zwei Nachrichten nicht viel sind.“","grade":1,"why":"Eine quantitative Bewertung übersieht die Bedeutung, die Jule dem Moment zugeschrieben hat.","response":"Jule: „Es ging um das Gefühl von Abstand, nicht die Zahl.“"}],"follow_good":[{"text":"„Welches Gefühl entstand aus dieser Geschichte, und was wäre eine kleine konkrete Bitte für das nächste Abendessen?“","grade":3,"why":"Führt nachvollziehbar von Deutung zu Gefühl und Wunsch.","response":"Jule: „Ich war traurig. Ich wünsche mir, dass wir vorher kurz klären, ob etwas Dringendes kommt.“"},{"text":"„Wollen wir besprechen, ob beim Essen grundsätzlich Handys erlaubt sein sollen?“","grade":2,"why":"Regel kann später nützlich sein, überspringt aber zunächst Jules Gefühl.","response":"Jule: „Ich möchte, dass er versteht, warum es mich getroffen hat.“"},{"text":"„Sam, können Sie versichern, dass Jule Ihre Priorität bleibt?“","grade":1,"why":"Beruhigung ist möglich, kann aber die vier Feedback-Schritte durch ein verlangtes Versprechen ersetzen.","response":"Sam: „Ich möchte zeigen, wie es sich praktisch ändern kann.“"}],"follow_repair":[{"text":"„Ich habe die Situation zu schnell erklären lassen. Erst die Beobachtung, dann Jules Deutung als Deutung – nicht als Urteil über Sam.“","grade":3,"why":"Repariert die Vermischung und eröffnet wieder das Feedback Wheel.","response":"Jule: „Genau, ich weiß ja nicht, was er gedacht hat.“"},{"text":"„Wir können die Nachrichten zeitlich genauer rekonstruieren.“","grade":2,"why":"Kann helfen, lässt die Beziehungserfahrung noch ungeklärt.","response":"Sam: „Die Zeiten kann ich sagen, aber ihr Gefühl verstehe ich noch nicht.“"},{"text":"„Vielleicht war das Ganze einfach ein Missverständnis.“","grade":1,"why":"Kann stimmen, wäre aber eine vorschnelle Abwertung der geäußerten Traurigkeit.","response":"Jule: „So fühlt es sich für mich nicht an.“"}],"model":"„Als du beim Essen Nachrichten geöffnet hast, habe ich mir erzählt, dass unser Abend dir nicht wichtig ist. Ich war traurig. Könnten wir künftig vorher sagen, wenn etwas Dringendes dazwischenkommt?“","rubric":["Beobachtbares Ereignis statt Charakterurteil","Deutung ausdrücklich als eigene Geschichte markiert","Gefühl benannt","Bitte konkret, freiwillig und gegenwartsnah"]},{"id":"fw-02","track":"Feedback Wheel","title":"Aus dem Vorwurf eine Bitte machen","skill":"Feedback Wheel: von globaler Kritik zu konkretem Anliegen führen","context":"Noah sagt immer wieder, dass Ava „nie hilft“. Ava wehrt sich gegen diese Pauschalisierung.","scene":[{"speaker":"Noah","text":"Du lässt mich mit dem ganzen Haushalt allein."},{"speaker":"Ava","text":"Das stimmt nicht. Ich putze am Wochenende."},{"speaker":"Noah","text":"Trotzdem denke ich jeden Morgen an alles."},{"speaker":"Ava","text":"Ich will mich nicht dauernd verteidigen."},{"speaker":"Noah","text":"Wenn das so bleibt, habe ich bald keine Energie mehr."},{"speaker":"Ava","text":"Dann sag mir bitte, was du genau brauchst."}],"anchor":"Das Feedback Wheel hilft, globale Vorwürfe in benennbare Beobachtung, eigene Bedeutung, Gefühle und einen verhandelbaren Wunsch zu übersetzen.","caution":"Eine Bitte ist keine versteckte Pflichtzuteilung; Zuständigkeiten müssen gemeinsam vereinbart werden.","first":[{"text":"„Noah, welches konkrete Ereignis von heute Morgen meinen Sie, und was war die Geschichte, die Sie daraus über Ihre gemeinsame Verantwortung gebildet haben?“","grade":3,"why":"Öffnet die vier Schritte und lässt Raum für eine genaue Bitte.","response":"Noah: „Die Schultasche war noch leer. Ich dachte, ich bin mit allem allein.“"},{"text":"„Ava, was übernehmen Sie bereits, das Noah vielleicht nicht sieht?“","grade":2,"why":"Hilft bei einer fairen Bilanz, wechselt jedoch wieder in den Rechtfertigungsmodus.","response":"Ava: „Vieles, aber mir wäre eine klare Bitte lieber.“"},{"text":"„Wollen wir eine Tabelle über alle Tätigkeiten führen?“","grade":1,"why":"Organisation kann sinnvoll sein, löst jedoch den emotionalen Teil der Rückmeldung noch nicht.","response":"Noah: „Eine Tabelle allein macht das Gefühl nicht weg.“"}],"follow_good":[{"text":"„Wie haben Sie sich dabei gefühlt, und welche konkrete Unterstützung wünschen Sie sich für morgen?“","grade":3,"why":"Übersetzt diffuse Überforderung in Gefühl und handhabbare Bitte.","response":"Noah: „Ich war erschöpft. Würdest du morgen die Schultasche übernehmen?“"},{"text":"„Wollen Sie gemeinsam eine neue Grundaufteilung planen?“","grade":2,"why":"Hilfreiche Lösung, allerdings fehlt zunächst die genaue Gefühlsbenennung.","response":"Ava: „Ja, wenn wir verstehen, was gerade schwierig ist.“"},{"text":"„Ava, können Sie Noah versprechen, ab sofort gerechter zu sein?“","grade":1,"why":"Zu global und normativ; nicht beobachtbar genug.","response":"Ava: „Ich möchte wissen, was ich konkret übernehmen soll.“"}],"follow_repair":[{"text":"„Ich möchte den allgemeinen Streit kurz verlassen: Ein Ereignis, eine eigene Deutung, ein Gefühl und eine umsetzbare Bitte. Noah, womit möchten Sie beginnen?“","grade":3,"why":"Repariert den globalen Rechtfertigungskreislauf.","response":"Noah: „Heute Morgen mit der Schultasche.“"},{"text":"„Wir können die Belastungsverteilung genauer aufschreiben.“","grade":2,"why":"Das kann später hilfreich sein, ohne zunächst das Feedback Wheel zu ersetzen.","response":"Noah: „Dann würde ich auch gerne sagen, wie es mir geht.“"},{"text":"„Vielleicht ist das Wort ‚nie‘ hier einfach das einzige Problem.“","grade":1,"why":"Sprachkorrektur allein reduziert Noahs Belastung auf Stilfragen.","response":"Noah: „Es gibt ja trotzdem eine echte Überlastung.“"}],"model":"„Als ich heute Morgen die leere Schultasche sah, habe ich mir erzählt, dass ich allein für alles verantwortlich bin. Ich war erschöpft. Kannst du morgen früh die Schultasche übernehmen?“","rubric":["Konkrete Beobachtung gewählt","Deutung von Fakt unterschieden","Gefühl statt versteckter Schuldzuweisung","Praktisch verhandelbare Bitte formuliert"]},{"id":"fw-03","track":"Feedback Wheel","title":"Feedback hören, ohne sich zu verteidigen","skill":"Empfangsseite des Feedback Wheel stärken","context":"Leo versucht, ein Feedback anzusprechen. Mara hat den Impuls, sofort ihre Absicht zu erklären.","scene":[{"speaker":"Leo","text":"Als du mich vorhin unterbrochen hast, habe ich gedacht, meine Meinung zählt nicht."},{"speaker":"Mara","text":"Ich wollte nur noch eine Sache ergänzen."},{"speaker":"Leo","text":"Ich weiß. Ich war trotzdem enttäuscht."},{"speaker":"Mara","text":"Ich möchte nicht, dass du glaubst, ich respektiere dich nicht."},{"speaker":"Leo","text":"Ich wünsche mir, dass du mich erst ausreden lässt."},{"speaker":"Mara","text":"Ich will darauf eingehen, ohne etwas zu versprechen, das ich nicht halten kann."}],"anchor":"Das Feedback Wheel umfasst auch eine zuhörende Seite: Wirkung anerkennen, eigene Absicht nicht zur Gegenwaffe machen und über eine realistische Bitte verhandeln.","caution":"Zuhören erfordert keine Zustimmung zu jeder Deutung; es geht um Anerkennung der erlebten Wirkung.","first":[{"text":"„Mara, können Sie zunächst wiedergeben, was Leo erlebt hat, bevor Sie Ihre Absicht erläutern?“","grade":3,"why":"Ermöglicht nicht-defensives Zuhören und trennt Wirkung von Absicht.","response":"Mara: „Er fühlte sich unwichtig, als ich ihn unterbrach. Das habe ich so nicht gewollt.“"},{"text":"„Mara, könnten Sie Leo sagen, dass Ihre Unterbrechung nicht abwertend gemeint war?“","grade":2,"why":"Absichtserklärung kann entlasten, kommt aber vor dem Verstehen der Wirkung.","response":"Leo: „Ich glaube dir das. Ich möchte trotzdem gehört werden.“"},{"text":"„Leo, könnten Sie Ihre Deutung weniger persönlich nehmen?“","grade":1,"why":"Selbstprüfung kann wichtig sein, verlegt aber die Verantwortung für das Unterbrechen vorschnell auf Leo.","response":"Leo: „Dann traue ich mich vielleicht nicht mehr, Feedback zu geben.“"}],"follow_good":[{"text":"„Was an Leos Bitte könnten Sie tatsächlich umsetzen, und wo brauchen Sie vielleicht eine realistische Absprache?“","grade":3,"why":"Übersetzt Verständnis in freiwillige konkrete Handlung.","response":"Mara: „Ich kann ihn ausreden lassen und bei dringenden Einfällen kurz nachfragen, ob ich unterbrechen darf.“"},{"text":"„Wäre eine Entschuldigung jetzt ein guter Schritt?“","grade":2,"why":"Entschuldigung ist denkbar, sollte aber von echtem Verständnis getragen werden.","response":"Mara: „Ja, ich würde mich für das Unterbrechen entschuldigen.“"},{"text":"„Wollen wir ein Zeichen vereinbaren, damit Leo Unterbrechungen künftig sofort stoppt?“","grade":1,"why":"Kann helfen, delegiert die Hauptverantwortung aber an Leo.","response":"Leo: „Ich möchte nicht dauernd die Stopp-Taste sein.“"}],"follow_repair":[{"text":"„Ich habe gerade zu schnell nach Ihrer Absicht gefragt. Mara, können wir zuerst hören, wie Leo den Moment erlebt hat, ohne dass Sie seine Deutung übernehmen müssen?“","grade":3,"why":"Repariert Defensivität und lässt Unterschiedlichkeit bestehen.","response":"Mara: „Ja. Ich kann seine Enttäuschung verstehen, auch wenn ich es anders meinte.“"},{"text":"„Wollen Sie beide noch einmal schildern, was zeitlich passiert ist?“","grade":2,"why":"Klärt Fakten, hält aber den Zugang zur Wirkung zunächst offen.","response":"Leo: „Ich möchte vor allem verstanden werden.“"},{"text":"„Dann muss Leo noch genauer erklären, weshalb er empfindlich reagiert.“","grade":1,"why":"Würde sein Feedback in eine Rechtfertigungspflicht verkehren.","response":"Leo: „Dann denke ich, es kommt nicht an.“"}],"model":"„Mara, bevor wir Ihre Absicht ansehen: Was hat Leo in diesem Moment erlebt? Sie müssen seiner Geschichte nicht zustimmen. Können Sie die Enttäuschung trotzdem anerkennen?“","rubric":["Wirkung vor Rechtfertigung gehört","Interpretation nicht als Fakt behandelt","Realistische Bitte verhandelbar","Gegenseitigkeit ohne Gleichmacherei"]},{"id":"ls-01","track":"Losing → Winning Strategies","title":"Recht haben oder verbunden bleiben","skill":"Winning Strategy: neugierig zuhören statt einen Beweisprozess gewinnen","context":"Paula und Deniz diskutieren dieselbe Verabredung zum dritten Mal. Beide erinnern den Zeitpunkt unterschiedlich.","scene":[{"speaker":"Paula","text":"Du hast gesagt, du bist um sieben zuhause."},{"speaker":"Deniz","text":"Nein, ich habe halb acht gesagt."},{"speaker":"Paula","text":"Ich habe es extra aufgeschrieben."},{"speaker":"Deniz","text":"Du kannst mir den Chat zeigen; ich weiß, was ich meinte."},{"speaker":"Paula","text":"Ich fühlte mich allein mit dem Abend."},{"speaker":"Deniz","text":"Ich will nicht als unzuverlässig gelten."}],"anchor":"Losing Strategy „Recht haben“ wird durch Zuhören, berechtigte Selbstvertretung und eine gemeinsame, überprüfbare Bitte ersetzt.","caution":"Fakten bleiben relevant, besonders bei Absprachen; der therapeutische Fokus darf berechtigte Verlässlichkeit nicht relativieren.","first":[{"text":"„Bevor wir die Uhrzeit klären: Paula, welche Wirkung hatte das Warten? Deniz, könnten Sie diese Wirkung einmal aufnehmen?“","grade":3,"why":"Bewahrt Sachklärung als späteren Schritt und eröffnet Verbindung.","response":"Deniz: „Sie war mit allem allein. Das hatte ich so nicht gesehen.“"},{"text":"„Wollen wir die Nachricht kurz gemeinsam ansehen?“","grade":2,"why":"Prüft den Fakt, kann aber den Streit als Sieger-Verlierer-Spiel verlängern.","response":"Paula: „Das könnten wir, aber mein Abend wird davon nicht leichter.“"},{"text":"„Paula, können Sie Deniz bitten, künftig genauer zu schreiben?“","grade":1,"why":"Vernünftiger Zukunftsschritt, überspringt noch die emotionale Wirkung.","response":"Deniz: „Ja, das wäre möglich. Trotzdem hängen wir am Vorwurf.“"}],"follow_good":[{"text":"„Wie könnte Deniz anerkennen, dass Paula den Abend allein trug, ohne eine falsche Erinnerung zu bestätigen?“","grade":3,"why":"Trennt Wirkung anerkennen von Faktenzugeständnis.","response":"Deniz: „Es tut mir leid, dass du so allein dastandest. Das will ich nächstes Mal vorher klären.“"},{"text":"„Welche genaue Formulierung soll künftig im Kalender stehen?“","grade":2,"why":"Konkrete Planung ist nützlich, kommt aber etwas schnell.","response":"Paula: „Gut. Aber schön wäre, wenn es ihn berührt.“"},{"text":"„Dann einigen wir uns einfach, dass niemand Schuld hat.“","grade":1,"why":"Entlastung wirkt bequem, vermeidet aber konkrete Verantwortung.","response":"Paula: „Jemand muss sich trotzdem um die Kinder kümmern.“"}],"follow_repair":[{"text":"„Ich habe Sie in eine Beweisfrage geführt. Was war die Auswirkung des Abends auf Sie beide – und welche klare Vereinbarung brauchen Sie künftig?“","grade":3,"why":"Repariert das Muster, ohne die Realität der Absprache zu leugnen.","response":"Paula: „Wir brauchen eine eindeutige Nachricht bei Verspätung.“"},{"text":"„Vielleicht ist es hilfreich, die Erinnerungslücke genauer zu untersuchen.“","grade":2,"why":"Kann klären, aber löst die Beziehungsebene zunächst nicht.","response":"Deniz: „Wahrscheinlich kann keiner den anderen überzeugen.“"},{"text":"„Könnten Sie einfach akzeptieren, dass beide Versionen gleich wahr sind?“","grade":1,"why":"Eine falsche Gleichsetzung kann reale Absprachen entwerten.","response":"Paula: „Wir hatten aber eine konkrete Organisation.“"}],"model":"„Mir fällt auf, dass Sie beide Ihre Erinnerung verteidigen. Paula, welche Wirkung hatte der Abend? Deniz, können Sie diese Wirkung verstehen, bevor wir klären, was organisatorisch geändert werden muss?“","rubric":["Recht-haben-Muster erkannt","Bereits geschehene Belastung ernst genommen","Fakt und Wirkung unterschieden","Realistische Absprache formuliert"]},{"id":"ls-02","track":"Losing → Winning Strategies","title":"Kontrolle als Schutzversuch","skill":"Winning Strategy: konkretes Bedürfnis verhandeln statt Regeln einseitig aufzuerlegen","context":"Eine vergangene Unehrlichkeit belastet das Paar; Kai möchte daher alle Freizeitpläne von Liv vorher genehmigen.","scene":[{"speaker":"Kai","text":"Nach dem Vorfall muss ich wissen, wo du bist."},{"speaker":"Liv","text":"Ich bin bereit, transparent zu sein, aber nicht um Erlaubnis zu fragen."},{"speaker":"Kai","text":"Sonst kann ich mich nicht entspannen."},{"speaker":"Liv","text":"Ich möchte Vertrauen aufbauen, ohne mich wieder wie ein Kind zu fühlen."},{"speaker":"Kai","text":"Ich will einfach nicht noch einmal überrascht werden."},{"speaker":"Liv","text":"Dann brauchen wir eine Vereinbarung, die wir beide tragen können."}],"anchor":"Losing Strategy „Kontrollieren“: nachvollziehbare Angst benennen, Verantwortung für eigenen Umgang mit ihr behalten und gegenseitig freiwillige Transparenz verhandeln.","caution":"Bei fortgesetzter Täuschung oder kontrollierendem Missbrauch sind Schutz und Einzelabklärung wichtiger als ein bloßes Kommunikationstraining.","first":[{"text":"„Kai, Ihre Angst ist verständlich. Welche konkrete Information würde Ihnen Sicherheit geben, ohne dass Liv um Erlaubnis bitten muss?“","grade":3,"why":"Trennt Sicherheitsbedürfnis von einseitiger Herrschaft über Livs Verhalten.","response":"Kai: „Eine Nachricht bei Planänderungen wäre schon hilfreich.“"},{"text":"„Könnten Sie beide eine gemeinsame Regel für Freizeitplanung aufschreiben?“","grade":2,"why":"Eine Vereinbarung kann nützen; ohne Blick auf Macht und Freiwilligkeit droht sie Kontrolle zu legitimieren.","response":"Liv: „Nur wenn wir beide wirklich zustimmen.“"},{"text":"„Liv, könnten Sie Kai vorübergehend alle Details mitteilen, damit er ruhiger wird?“","grade":1,"why":"Transparenz kann freiwillig hilfreich sein; so könnte sie aber zur unbegrenzten Beruhigungspflicht werden.","response":"Liv: „Ich kann nicht dauerhaft seine Angst regulieren.“"}],"follow_good":[{"text":"„Woran merken Sie beide, dass Transparenz freiwillig und verhandelbar bleibt – und wie gehen Sie mit Angst um, wenn gerade keine Nachricht da ist?“","grade":3,"why":"Verankert die Grenze zwischen Abmachung und Kontrolle.","response":"Kai: „Ich muss lernen, nicht sofort nachzufragen.“"},{"text":"„Wollen Sie eine feste Nachricht pro Abend vereinbaren?“","grade":2,"why":"Als erste konkrete Absprache möglich; sollte Raum für persönliche Autonomie lassen.","response":"Liv: „Vielleicht, aber nicht als tägliche Prüfung.“"},{"text":"„Vielleicht verschwinden die Sorgen, sobald Sie die Regel konsequent einhalten.“","grade":1,"why":"Stellt eine unbelegte Wirkung in Aussicht; Angst und Verantwortung bleiben bestehen.","response":"Kai: „Ich fürchte, ich würde trotzdem kontrollieren wollen.“"}],"follow_repair":[{"text":"„Ich möchte korrigieren, dass ich Kontrolle wie eine neutrale Regel behandelt habe. Wir prüfen erst, was jeder freiwillig vereinbaren kann und was private Entscheidung bleibt.“","grade":3,"why":"Repariert den Machtaspekt und ermöglicht verantwortliche Selbstvertretung.","response":"Liv: „So kann ich eher über Transparenz sprechen.“"},{"text":"„Könnten wir vorerst eine zeitlich begrenzte Vereinbarung testen?“","grade":2,"why":"Kann funktionieren, wenn sie freiwillig ist; Machtasymmetrie bleibt aktiv zu prüfen.","response":"Kai: „Ja, wir müssten Grenzen festlegen.“"},{"text":"„Dann braucht Kai eben mehr Geduld.“","grade":1,"why":"Geduld ist kein hinreichender Ersatz für Verantwortungsarbeit und konkrete Transparenz.","response":"Kai: „Ich weiß gerade nicht, was ich selbst tun kann.“"}],"model":"„Kai, die Angst nach der früheren Unehrlichkeit verdient Raum. Sie gibt aber kein automatisches Recht, Livs Freizeit zu genehmigen. Welche begrenzte Transparenz wäre für beide freiwillig und sinnvoll?“","rubric":["Sicherheitsbedürfnis anerkannt","Kontrolle nicht als Lösung normalisiert","Freiwilligkeit und Autonomie geschützt","Selbstregulation konkret berücksichtigt"]},{"id":"ls-03","track":"Losing → Winning Strategies","title":"Alles ungefiltert aussprechen","skill":"Winning Strategy: respektvolle Selbstvertretung statt ungezügelter Selbstausdruck","context":"Rita sagt, Ehrlichkeit bedeute, jeden Ärger sofort auszusprechen. Für Jo wird daraus eine lange Liste früherer Fehler.","scene":[{"speaker":"Rita","text":"Ich muss doch sagen dürfen, was mich stört."},{"speaker":"Jo","text":"Dann kommen zehn Dinge auf einmal."},{"speaker":"Rita","text":"Ich halte nichts zurück, das ist doch ehrlich."},{"speaker":"Jo","text":"Ich verliere nach dem zweiten Vorwurf den Faden."},{"speaker":"Rita","text":"Wenn ich es nicht sofort sage, platze ich."},{"speaker":"Jo","text":"Ich würde lieber einen Punkt wirklich besprechen."}],"anchor":"Losing Strategy „ungezügelter Selbstausdruck“: Selbstvertretung bleibt wichtig, aber Zeitpunkt, Dosis und Respekt machen sie beziehungsfähig.","caution":"Affektregulation ist keine Aufforderung, berechtigte Beschwerden zu verschweigen.","first":[{"text":"„Rita, welcher eine Punkt ist Ihnen gerade am wichtigsten, und wie könnten Sie ihn als konkrete Beobachtung und Bitte ausdrücken?“","grade":3,"why":"Bewahrt Ehrlichkeit und reduziert Überflutung ohne Verbote.","response":"Rita: „Dass Jo Termine oft erst sehr spät absagt. Ich möchte früher Bescheid wissen.“"},{"text":"„Jo, welche der vielen Aussagen könnten Sie heute zuerst beantworten?“","grade":2,"why":"Gibt Jo Struktur, verlagert aber die Auswahl und Last auf die überforderte Person.","response":"Jo: „Ich kann einen Punkt nehmen, aber brauche dann Ruhe.“"},{"text":"„Rita, könnten Sie Ihre Anliegen sammeln und sie alle am Wochenende ansprechen?“","grade":1,"why":"Zeitplanung ist denkbar, kann aber die Liste nur verzögert und geballt wiederholen.","response":"Rita: „Dann staut sich bei mir wieder alles.“"}],"follow_good":[{"text":"„Wie kann Rita diese konkrete Bitte stellen und Jo darauf reagieren, ohne weitere alte Themen dazuzunehmen?“","grade":3,"why":"Übt eine begrenzte, dialogfähige Kommunikation.","response":"Jo: „Mit einem Punkt kann ich umgehen, auch wenn ich nicht zustimme.“"},{"text":"„Wollen Sie eine feste Gesprächsdauer festlegen?“","grade":2,"why":"Kann Überflutung verhindern, reicht ohne Priorisierung der Themen noch nicht aus.","response":"Rita: „Das würde helfen, wenn ich dabei nicht alles unterbringen muss.“"},{"text":"„Dann sollten alle alten Vorwürfe erst einmal komplett ruhen.“","grade":1,"why":"Zu pauschal; unverarbeitete Anliegen könnten dadurch verschwinden.","response":"Rita: „Einige Dinge müssen trotzdem besprochen werden.“"}],"follow_repair":[{"text":"„Ich habe Ihnen eben eine Sammelliste empfohlen, statt den Stil zu verändern. Nehmen wir eine beobachtbare Szene und eine Bitte, die Jo beantworten kann.“","grade":3,"why":"Repariert die Überflutung mit einer konkreten Alternative.","response":"Jo: „Genau, dann kann ich bei dem Thema bleiben.“"},{"text":"„Wollen wir über Regeln für Unterbrechungen sprechen?“","grade":2,"why":"Hilfreich, fokussiert aber nur einen Teil der Überforderung.","response":"Rita: „Ich glaube, es sind auch meine vielen Beispiele.“"},{"text":"„Rita, Ehrlichkeit braucht eben immer Zurückhaltung.“","grade":1,"why":"Zu allgemein und potenziell moralisierend; der konkrete Skill fehlt.","response":"Rita: „Aber was soll ich dann sagen?“"}],"model":"„Rita, Ihre Anliegen sollen Raum haben. Wenn zehn Vorwürfe gleichzeitig kommen, verlieren Sie Jo. Welcher eine Punkt ist heute zentral – und welche konkrete Veränderung wünschen Sie sich dazu?“","rubric":["Selbstvertretung ausdrücklich erlaubt","Ein Anliegen priorisiert","Respektvolle Form statt geballtem Angriff","Konkrete Bitte statt Charakterurteil"]},{"id":"ls-04","track":"Losing → Winning Strategies","title":"Zurückzahlen statt reparieren","skill":"Winning Strategy: Verletzung klar vertreten, ohne Vergeltung als Antwort","context":"Nach einem vergessenen Geburtstag lädt Felix absichtlich niemanden zu einem für Anna wichtigen Termin ein.","scene":[{"speaker":"Anna","text":"Du hast mich bei dem Fest einfach nicht informiert."},{"speaker":"Felix","text":"Du hast meinen Geburtstag auch vergessen."},{"speaker":"Anna","text":"Das habe ich später versucht wiedergutzumachen."},{"speaker":"Felix","text":"Ich wollte, dass du merkst, wie sich das anfühlt."},{"speaker":"Anna","text":"Das hat mich verletzt, aber ich verstehe den Zusammenhang nicht."},{"speaker":"Felix","text":"Ich wollte nicht schon wieder der Einzige sein, dem etwas wichtig ist."}],"anchor":"Losing Strategy „Vergeltung“: verletzte Bedürfnisse offen benennen und reparierbare Schritte wählen, statt dem Gegenüber denselben Schmerz zuzufügen.","caution":"Reparatur erfordert nicht, dass die frühere Verletzung bagatellisiert oder sofort vergeben wird.","first":[{"text":"„Felix, der vergessene Geburtstag war schmerzhaft. Wie könnten Sie diesen Schmerz deutlich sagen, ohne Anna absichtlich auszuschließen?“","grade":3,"why":"Hält emotionale Wirklichkeit und Verantwortung für Vergeltung zusammen.","response":"Felix: „Ich hätte sagen können, dass mich das Vergessen immer noch verletzt.“"},{"text":"„Anna, könnten Sie den Geburtstag noch einmal anerkennen?“","grade":2,"why":"Kann Verbindung stiften, lässt aber Felix’ Entscheidung zur Vergeltung zunächst unberührt.","response":"Anna: „Ja, aber ich möchte auch über das Fest sprechen.“"},{"text":"„Wollen wir zunächst vereinbaren, dass beide künftig Termine eintragen?“","grade":1,"why":"Organisation hilft, aber die Vergeltungsabsicht bleibt ungeklärt.","response":"Felix: „Es ging ehrlich gesagt nicht nur um Termine.“"}],"follow_good":[{"text":"„Was wäre ein erster Reparaturschritt für das bewusste Ausschließen, und wie bekommt zugleich der alte Geburtstag Raum?“","grade":3,"why":"Verantwortung und frühere Verletzung werden weder vertauscht noch gegenseitig annulliert.","response":"Felix: „Ich kann mein Ausschließen klar entschuldigen. Und den Geburtstag würde ich gern separat besprechen.“"},{"text":"„Wäre eine wechselseitige Entschuldigung jetzt hilfreich?“","grade":2,"why":"Kann passen, könnte aber die Asymmetrie der bewussten Vergeltung verwischen.","response":"Anna: „Ich möchte wissen, dass er das Ausschließen nicht wiederholt.“"},{"text":"„Dann ist es doch am besten, wenn beide einfach einen Schlussstrich ziehen.“","grade":1,"why":"Verkürzt Reparatur auf Vergessen statt Verantwortung.","response":"Felix: „Dann wäre mein ursprünglicher Schmerz auch weggewischt.“"}],"follow_repair":[{"text":"„Ich habe die alten und neuen Verletzungen eben vermischt. Felix, Ihr Schmerz ist real – und die absichtliche Ausladung braucht eigene Verantwortung.“","grade":3,"why":"Korrigiert eine falsche Gleichsetzung und schützt beide Erlebnisse.","response":"Felix: „Ich kann beides sehen, auch wenn es unangenehm ist.“"},{"text":"„Wollen Sie nacheinander beide Situationen ausführlich schildern?“","grade":2,"why":"Hilft der Faktenklärung, kann jedoch in Buchhaltung der Schuld kippen.","response":"Anna: „Ja, wenn es nicht darum geht, wer mehr gelitten hat.“"},{"text":"„Vielleicht sind beide Dinge einfach gleichermaßen verletzend.“","grade":1,"why":"Ein solches Gleichheitsurteil könnte Verantwortung für die bewusste Vergeltung verschleiern.","response":"Anna: „Mir war das Fest absichtlich vorenthalten worden.“"}],"model":"„Felix, Ihr Schmerz über den Geburtstag verdient Raum. Die bewusste Ausladung hat Anna zusätzlich verletzt. Wie können Sie dafür Verantwortung übernehmen und den früheren Schmerz ohne Gegenschlag benennen?“","rubric":["Vergeltungsabsicht benannt","Frühere Verletzung anerkannt","Eigenverantwortung für neue Verletzung nicht relativiert","Konkrete Reparatur vorgeschlagen"]},{"id":"ls-05","track":"Losing → Winning Strategies","title":"Rückzug oder Selbstschutz?","skill":"Winning Strategy: verbindliche Distanz statt passiv-aggressivem Kontaktabbruch","context":"Eva reagiert auf Konflikte mit Schweigen. Micah erlebt das als Bestrafung und drängt dann stärker.","scene":[{"speaker":"Micah","text":"Du redest nach Streit oft den ganzen Abend nicht mit mir."},{"speaker":"Eva","text":"Ich kann dann nicht mehr."},{"speaker":"Micah","text":"Ich frage zehnmal, was los ist."},{"speaker":"Eva","text":"Genau dadurch brauche ich noch mehr Abstand."},{"speaker":"Micah","text":"Ich habe Angst, dass du mich ganz ausschließt."},{"speaker":"Eva","text":"Ich will Ruhe, aber nicht immer wieder diesen Kreislauf."}],"anchor":"Losing Strategy „Rückzug“ unterscheidet sich von verantwortlicher Distanz: eine Pause mit Ankündigung, Selbstregulation und vereinbarter Rückkehr schützt Kontakt.","caution":"Bei Bedrohung oder fehlender Sicherheit darf Distanz unbegrenzt zum Selbstschutz nötig sein; gemeinsamer Rückkehrdruck wäre unangemessen.","first":[{"text":"„Eva, könnten Sie einen kurzen Time-out mit einer realistischen Rückkehr ankündigen, und Micah könnte in dieser Zeit auf Nachfragen verzichten?“","grade":3,"why":"Übersetzt reaktiven Rückzug und Verfolgung in zwei kontrollierbare Handlungen.","response":"Eva: „Ich könnte sagen, ich komme in einer Stunde wieder.“ Micah: „Mit der Zusage schaffe ich das Warten eher.“"},{"text":"„Micah, was passiert innerlich, wenn Eva nicht antwortet?“","grade":2,"why":"Hilfreiche Emotionserkundung; Eva braucht dennoch einen sicheren Weg zur Pause.","response":"Micah: „Ich fühle mich verlassen und frage dann immer weiter.“"},{"text":"„Eva, was müsste Micah tun, damit Sie gar keinen Rückzug mehr brauchen?“","grade":1,"why":"Kann Bedarfe klären, macht aber die Selbstregulation einseitig von Micah abhängig.","response":"Eva: „Manchmal brauche ich unabhängig davon Zeit für mich.“"}],"follow_good":[{"text":"„Was ist für beide eine glaubwürdige Pausenvereinbarung – und wie beginnen Sie bei der Rückkehr das Gespräch wieder?“","grade":3,"why":"Trainiert Durchführung und Wiedereinstieg, nicht nur die Ankündigung.","response":"Eva: „Mit einem kurzen Satz, was ich verstanden habe.“"},{"text":"„Möchten Sie die Stunde als allgemeine Regel festlegen?“","grade":2,"why":"Kann hilfreich sein, muss aber situativ und einvernehmlich bleiben.","response":"Micah: „Bei manchen Streits reicht auch eine kürzere Pause.“"},{"text":"„Dann ist das Schweigen künftig ja kein Problem mehr.“","grade":1,"why":"Würde Wirkung und bisherige Gewohnheit zu schnell für gelöst erklären.","response":"Eva: „Wir müssen das erst üben.“"}],"follow_repair":[{"text":"„Ich habe zu sehr Micahs Nachfragen behandelt. Eva braucht eine verantwortliche Pause und Micah ein verlässliches Signal der Rückkehr. Können wir beides konkret machen?“","grade":3,"why":"Korrigiert die einseitige Zuordnung und benennt den gemeinsamen Zyklus.","response":"Micah: „Damit könnte ich besser leben.“"},{"text":"„Wollen Sie für den nächsten Streit einen kurzen Stopp-Satz vorbereiten?“","grade":2,"why":"Ein guter Einstieg; Rückkehr und Wiedereinstieg fehlen noch.","response":"Eva: „Ja, und ich möchte sagen, wann ich wieder da bin.“"},{"text":"„Am besten geben Sie sich nach Streit einfach mehr Freiraum.“","grade":1,"why":"Zu vage und kann das strafende Schweigen fortsetzen.","response":"Micah: „Dann weiß ich noch immer nicht, ob sie wiederkommt.“"}],"model":"„Eva, eine Pause ist erlaubt. Sie unterscheidet sich vom strafenden Schweigen, wenn Sie sie ankündigen und zurückkehren. Micah, in der vereinbarten Zeit verzichten Sie auf das Nachsetzen. Was wäre für beide machbar?“","rubric":["Schutz und Vergeltung im Rückzug unterschieden","Ankündigung plus freiwillige Rückkehr","Nachsetzen in den Blick genommen","Keinen Kontakt unter unsicheren Bedingungen erzwungen"]}];
